212	
213		user, err := h.store.UserByID(userID)
214		if err != nil {
215			response.JSONServerError(w, r, err)
216			return
217		}
218	
219		if user == nil {
220			response.JSONNotFound(w, r)
221			return
222		}
223	
224		user.UseTimezone(request.UserTimezone(r))
225		response.JSON(w, r, user)
