326	func (h *greaderHandler) quickAddHandler(w http.ResponseWriter, r *http.Request) {
327		userID := request.UserID(r)
328		clientIP := request.ClientIP(r)
329	
330		slog.Debug("[GoogleReader] Handle /subscription/quickadd",
331			slog.String("handler", "quickAddHandler"),
332			slog.String("client_ip", clientIP),
333			slog.String("user_agent", r.UserAgent()),
334			slog.Int64("user_id", userID),
335		)
336	
337		err := r.ParseForm()
338		if err != nil {
339			response.JSONBadRequest(w, r, err)
340			return
341		}
342	
343		feedURL := r.Form.Get(paramQuickAdd)
344		if !urllib.IsAbsoluteURL(feedURL) {
345			response.JSONBadRequest(w, r, fmt.Errorf("googlereader: invalid URL: %s", feedURL))
346			return
347		}
348	
349		requestBuilder := fetcher.NewRequestBuilder().
350			WithTimeout(config.Opts.HTTPClientTimeout()).
351			WithProxyRotator(proxyrotator.ProxyRotatorInstance).
352			WithUserAgent("", config.Opts.HTTPClientUserAgent())
353	
354		var rssBridgeURL string
355		var rssBridgeToken string
356		if intg, err := h.store.Integration(userID); err == nil && intg != nil && intg.RSSBridgeEnabled {
357			rssBridgeURL = intg.RSSBridgeURL
358			rssBridgeToken = intg.RSSBridgeToken
359		}
360	
361		subscriptions, localizedError := mfs.NewSubscriptionFinder(requestBuilder).FindSubscriptions(feedURL, rssBridgeURL, rssBridgeToken)
362		if localizedError != nil {
363			response.JSONServerError(w, r, localizedError.Error())
364			return
365		}
366	
367		if len(subscriptions) == 0 {
368			response.JSON(w, r, quickAddResponse{
369				NumResults: 0,
370			})
371			return
372		}
373	
374		toSubscribe := Stream{FeedStream, subscriptions[0].URL}
375		category := Stream{NoStream, ""}
376		newFeed, err := subscribe(toSubscribe, category, "", h.store, userID)
377		if err != nil {
378			if errors.Is(err, errCategoryNotFound) {
379				response.JSONBadRequest(w, r, err)
380			} else {
381				response.JSONServerError(w, r, err)
382			}
383			return
384		}
385	
386		slog.Debug("[GoogleReader] Added a new feed",
387			slog.String("handler", "quickAddHandler"),
388			slog.String("client_ip", clientIP),
389			slog.String("user_agent", r.UserAgent()),
390			slog.Int64("user_id", userID),
391			slog.String("feed_url", newFeed.FeedURL),
392		)
393	
394		response.JSON(w, r, quickAddResponse{
395			NumResults: 1,
396			Query:      newFeed.FeedURL,
397			StreamID:   feedPrefix + strconv.FormatInt(newFeed.ID, 10),
398			StreamName: newFeed.Title,
